Here is the commit message:
net: phy: marvell: Fix invalid comparison in the resume and
 suspend functions

This bug resulted in only the current mode being resumed and suspended when
the PHY supported both fiber and copper modes and when the PHY only supported
copper mode the fiber mode would incorrectly be attempted to be resumed and
suspended.

Fixes: 3758be3dc162 ("Marvell phy: add functions to suspend and resume both interfaces: fiber and copper links.")
Signed-off-by: Kurt Cancemi <kurt@x64architecture.com>
Reviewed-by: Andrew Lunn <andrew@lunn.ch>
Link: https://lore.kernel.org/r/20220312201512.326047-1-kurt@x64architecture.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug was caused by an incorrect conditional check in the `marvell_suspend` and `marvell_resume` functions, where the code was checking if fiber mode was not supported instead of checking if it was supported. This led to improper handling of the suspension and resumption of the fiber mode, resulting in only the current mode being managed and incorrect attempts to suspend or resume fiber mode when it was not supported.

Here is the patch:
  */
 static int marvell_suspend(struct phy_device *phydev)
 {
 	int err;

 	/* Suspend the fiber mode first */
-	if (!linkmode_test_bit(ETHTOOL_LINK_MODE_FIBRE_BIT,
-			       phydev->supported)) {
+	if (linkmode_test_bit(ETHTOOL_LINK_MODE_FIBRE_BIT,
+			      phydev->supported)) {
 		err = marvell_set_page(phydev, MII_MARVELL_FIBER_PAGE);
 		if (err < 0)
 			goto error;

 		/* With the page set, use the generic suspend */
 		err = genphy_suspend(phydev);
 		if (err < 0)
 			goto error;

 		/* Then, the copper link */
 		err = marvell_set_page(phydev, MII_MARVELL_COPPER_PAGE);
 		if (err < 0)
 			goto error;
 	}

 	/* With the page set, use the generic suspend */
 	return genphy_suspend(phydev);

 error:
 	marvell_set_page(phydev, MII_MARVELL_COPPER_PAGE);
 	return err;
 }

  */
 static int marvell_resume(struct phy_device *phydev)
 {
 	int err;

 	/* Resume the fiber mode first */
-	if (!linkmode_test_bit(ETHTOOL_LINK_MODE_FIBRE_BIT,
-			       phydev->supported)) {
+	if (linkmode_test_bit(ETHTOOL_LINK_MODE_FIBRE_BIT,
+			      phydev->supported)) {
 		err = marvell_set_page(phydev, MII_MARVELL_FIBER_PAGE);
 		if (err < 0)
 			goto error;

 		/* With the page set, use the generic resume */
 		err = genphy_resume(phydev);
 		if (err < 0)
 			goto error;

 		/* Then, the copper link */
 		err = marvell_set_page(phydev, MII_MARVELL_COPPER_PAGE);
 		if (err < 0)
 			goto error;
 	}

 	/* With the page set, use the generic resume */
 	return genphy_resume(phydev);

 error:
 	marvell_set_page(phydev, MII_MARVELL_COPPER_PAGE);
 	return err;
 }



